     1	package org.springframework.samples.petclinic.rest.function.owner;
     2	
     3	import java.util.Map;
     4	
     5	import org.springframework.samples.petclinic.model.Owner;
     6	
     7	/**
     8	 * Region resolution for owner identity. {@link #forPostcode} maps an owner to a region code (the
     9	 * {@code REGION} half of the {@code <REGION>-<HASH8>} customerCode), preferring the postcode: a
    10	 * 4-digit postcode in a known range maps to its region (NSW 2000-2099, VIC 3000-3099, QLD
    11	 * 4000-4099); otherwise it falls back to the city-to-region table (Sydney/NSW, Melbourne/VIC,
    12	 * Brisbane/QLD), and anything unresolved is {@code "UNKNOWN"}. The derived {@code locality} now
    13	 * reads that same region back off the customerCode (see {@link #region}).
    14	 */
    15	public final class OwnerLocality {
    16	
    17	    private static final Map<String, String> CITY_REGION = Map.of(
    18	            "Sydney", "NSW", "Melbourne", "VIC", "Brisbane", "QLD");
    19	
    20	    private OwnerLocality() {
    21	    }
    22	
    23	    /** Region for the owner's identity, derived from the postcode with the city as fallback. */
    24	    public static String forPostcode(String postcode, String city) {
    25	        String byPostcode = byPostcode(postcode);
    26	        if (byPostcode != null) {
    27	            return byPostcode;
    28	        }
    29	        return CITY_REGION.getOrDefault(city, "UNKNOWN");
    30	    }
    31	
    32	    /** Locality: the region carried in the {@code <REGION>-<HASH8>} customerCode identity. */
    33	    public static String region(Owner owner) {
    34	        String code = owner.getCustomerCode();
    35	        int dash = code == null ? -1 : code.indexOf('-');
    36	        return dash < 0 ? "UNKNOWN" : code.substring(0, dash);
    37	    }
    38	
    39	    private static String byPostcode(String postcode) {
    40	        if (postcode == null) {
    41	            return null;
    42	        }
    43	        int value = Integer.parseInt(postcode);
    44	        if (value >= 2000 && value <= 2099) {
    45	            return "NSW";
    46	        }
    47	        if (value >= 3000 && value <= 3099) {
    48	            return "VIC";
    49	        }
    50	        if (value >= 4000 && value <= 4099) {
    51	            return "QLD";
    52	        }
    53	        return null;
    54	    }
    55	}

