     3	import java.nio.charset.StandardCharsets;
     4	import java.security.MessageDigest;
     5	import java.security.NoSuchAlgorithmException;
     6	
     7	import org.springframework.samples.petclinic.model.Owner;
     8	
     9	/**
    10	 * Single source of truth for an owner's {@code identityKey}, the derived value all duplicate
    11	 * detection is expressed through: the SHA-256 hex of {@code normalizedTelephone + '|' + lowerEmail +
    12	 * '|' + soundex(lastName)}. Two owners are duplicates only when their whole identityKey is equal, so
    13	 * members of the same household (same {@link Soundex} last name and postcode) with different
    14	 * telephones have distinct keys and are a soft match, not a hard duplicate.
    15	 */
    16	public final class OwnerIdentity {
    17	
    18	    private OwnerIdentity() {
    19	    }
    20	
    21	    public static String key(Owner owner) {
    22	        return sha256Hex(orEmpty(owner.getTelephone()) + "|" + orEmpty(owner.getEmail()) + "|"
    23	                + Soundex.encode(owner.getLastName()));
    24	    }
    25	
    26	    /** Full lower-case hex SHA-256 of the UTF-8 bytes of {@code value}. */
    27	    private static String sha256Hex(String value) {
    28	        try {
    29	            byte[] digest = MessageDigest.getInstance("SHA-256").digest(value.getBytes(StandardCharsets.UTF_8));
    30	            StringBuilder sb = new StringBuilder(digest.length * 2);
    31	            for (byte b : digest) {
    32	                sb.append(String.format("%02x", b));
    33	            }
    34	            return sb.toString();
    35	        }
    36	        catch (NoSuchAlgorithmException ex) {
    37	            throw new IllegalStateException(ex);
    38	        }
    39	    }
    40	
    41	    private static String orEmpty(String value) {
    42	        return value == null ? "" : value;
    43	    }
    44	}

