     7	/**
     8	 * Marketing segment for an owner, formatted {@code <TIER>_<AREA>}. TIER is {@code PREMIUM} at
     9	 * membership level 3 or more, otherwise {@code STANDARD}; AREA is {@code METRO} when the owner's
    10	 * {@link OwnerLocality#region locality} is a known region (NSW, VIC or QLD), otherwise
    11	 * {@code REGIONAL}.
    12	 */
    13	public final class OwnerSegment {
    14	
    15	    private static final Set<String> METRO_REGIONS = Set.of("NSW", "VIC", "QLD");
    16	
    17	    private OwnerSegment() {
    18	    }
    19	
    20	    /** The owner's segment, e.g. {@code "STANDARD_METRO"}. */
