    25	    private static String tier(Owner owner) {
    26	        Integer level = owner.getMembershipLevel();
    27	        int effective = level != null ? level : OwnerMembershipLevel.of(owner);
    28	        return effective >= 3 ? "PREMIUM" : "STANDARD";
    29	    }
