     3	import java.time.LocalDate;
     4	
     5	import org.springframework.samples.petclinic.model.Owner;
     6	
     7	/**
     8	 * Membership scoring for an owner. Points accrue from independent factors — 2 for a supplied email,
     9	 * 1 for a {@code namesakeCount} of 0, 2 for a household of three or more occupants (the owner plus
    10	 * their pets) and 3 for tenure of more than 365 days since {@code registrationDate} — and are banded
    11	 * into a level of 1 through 4.
    12	 */
    13	public final class OwnerMembershipLevel {
    14	
    15	    private OwnerMembershipLevel() {
    16	    }
    17	
    18	    /** The owner's membership points. */
    19	    public static int points(Owner owner) {
    20	        int points = 0;
    21	        if (owner.getEmail() != null) {
    22	            points += 2;
    23	        }
    24	        if (Integer.valueOf(0).equals(owner.getNamesakeCount())) {
    25	            points += 1;
    26	        }
    27	        if (1 + owner.getPets().size() >= 3) {
    28	            points += 2;
    29	        }
    30	        if (tenureFiscalYears(owner) >= 1) {
    31	            points += 3;
    32	        }
    33	        return points;
    34	    }
    35	
    36	    /** The owner's membership level, 1 through 4, banded from {@link #points(Owner)}. */
    37	    public static int of(Owner owner) {
    38	        int points = points(owner);
    39	        if (points <= 1) {
    40	            return 1;
    41	        }
    42	        if (points <= 3) {
    43	            return 2;
    44	        }
    45	        if (points <= 5) {
    46	            return 3;
    47	        }
    48	        return 4;
    49	    }
    50	
    51	    private static int tenureFiscalYears(Owner owner) {
    52	        LocalDate registrationDate = owner.getRegistrationDate();
    53	        return registrationDate == null ? 0 : FiscalYear.of(LocalDate.now()) - FiscalYear.of(registrationDate);
    54	    }
    55	}

