     5	/**
     6	 * Single source of truth for the fiscal year a date falls in, where the fiscal year starts on
     7	 * 1 July and is named by the calendar year it ends in (1 July 2025 to 30 June 2026 is fiscal 2026).
     8	 * Every date-derived value that used to key off the calendar year — the membership number's year
     9	 * segment, the fiscalYear label, tenure — reads its year basis from here.
    10	 */
    11	public final class FiscalYear {
    12	
    13	    private FiscalYear() {
    14	    }
    15	
    16	    /** The fiscal year (starting 1 July) that {@code date} falls in. */
    17	    public static int of(LocalDate date) {
    18	        return date.getMonthValue() >= 7 ? date.getYear() + 1 : date.getYear();
    19	    }
    20	
    21	    /** The two-digit fiscal-year segment, e.g. {@code "26"}. */
    22	    public static String twoDigit(LocalDate date) {
    23	        return String.format("%02d", of(date) % 100);
    24	    }
    25	
    26	    /** The fiscal-year label {@code "FY<YY>"}, e.g. {@code "FY26"}. */
    27	    public static String label(LocalDate date) {
    28	        return "FY" + twoDigit(date);
    29	    }
    30	}

